import { Field, ID, InputType, Int } from '@nestjs/graphql';
import { Gender } from '@ridy/database';

@InputType()
export class DocumentPairInput {
  @Field(() => ID)
  documentId!: number;

  @Field(() => ID)
  mediaId!: number;
}

@InputType()
export class CompleteRegistrationInput {
  @Field(() => String)
  firstName!: string;
  @Field(() => String)
  lastName!: string;
  @Field(() => String, { nullable: true })
  certificateNumber?: string;
  @Field(() => String, { nullable: true })
  email?: string;
  @Field(() => Int, { nullable: true })
  carProductionYear?: number;
  @Field(() => String, { nullable: true })
  carPlate?: string;
  @Field(() => ID)
  profilePictureId!: number;
  @Field(() => Gender)
  gender!: Gender;
  @Field(() => Boolean, { nullable: true })
  canDeliver?: boolean;
  @Field(() => String, { nullable: true })
  address?: string;
  @Field(() => String, { nullable: true })
  city?: string;
  @Field(() => String, { nullable: true })
  vehicleOwnership?: string;
  @Field(() => String, { nullable: true })
  aadhaarNumber?: string;
  @Field(() => String, { nullable: true })
  panNumber?: string;
  @Field(() => String, { nullable: true })
  dob?: string;
  @Field(() => ID, { nullable: true })
  carId?: number;
  @Field(() => ID, { nullable: true })
  carColorId?: number;
  @Field(() => [DocumentPairInput])
  documentPairs!: DocumentPairInput[];
  @Field(() => [ID], { nullable: true })
  legacyDocumentIds?: number[];
  @Field(() => ID, { nullable: true })
  serviceId?: number;
}
